// embeddings: Array<{ id, vec, norm, tag, ...18 more fields }>  (array-of-structs)
// scoring loop touches only .vec and .norm per element
function scoreEmbeddings(embeddings, query) {
  let best = -Infinity;
  for (const e of embeddings) {
    const s = dot(e.vec, query) / e.norm;
    if (s > best) best = s;
  }
  return best;
}

function classify(counts) {
  const { cycles, instructions, cacheMisses, llcMisses } = counts;
  const ipc = cycles / instructions;          // instructions per cycle
  const dramShare = llcMisses / cacheMisses;
  if (ipc >= 2) return 'memory-bound';
  if (dramShare > 0.5) return 'compute-bound';
  return 'ambiguous';
}

