function summarize(c) {
  // c: { cycles, instructions, branchMisses, branches, cacheMisses, llcMisses }
  const ipc = c.instructions / c.cycles;
  const branchMissRate = c.branchMisses / c.cycles;        // 'how often we mispredict'
  const verdict = ipc < 1 ? 'stalled' : 'healthy';
  return {
    ipc: ipc.toFixed(2),
    branchMissRate: (branchMissRate * 100).toFixed(1) + '%',
    verdict,
  };
}
